mapper.select:
select id, tenant_id, email, display_name, status, profile, version, deleted, created_at, updated_at
from sys_user
where tenant_id = #{tenantID}
  and id = #{id}
  and deleted = false

select id, tenant_id, email, display_name, status, profile, version, deleted, created_at, updated_at
from sys_user

  tenant_id = #{tenantID}
  and deleted = false

    and status = #{status}


order by id
